import{_ as a,o as e,c as d,a2 as i}from"./chunks/framework.Bg-Zxr5O.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/Combining-Data-Files.md","filePath":"manual-zh/Combining-Data-Files.md","lastUpdated":1785684581000}'),o={name:"manual-zh/Combining-Data-Files.md"};function r(l,t,n,s,_,c){return e(),d("div",null,[...t[0]||(t[0]=[i('<h2 id="_10-合并数据文件" tabindex="-1">10 合并数据文件 <a class="header-anchor" href="#_10-合并数据文件" aria-label="Permalink to &quot;10 合并数据文件&quot;">​</a></h2><p>本章介绍用于将系统文件、便携文件以及已打开的数据集中的数据合并，以构成一个新的活动数据集的命令。这些命令可通过以下方式合并数据文件：</p><ul><li><code>ADD FILES</code> 交错或追加来自各输入文件的个案。它用于具有公共变量、但个案集合不同的输入文件。</li><li><code>MATCH FILES</code> 将多个输入文件中相匹配的个案的数据合并在一起。它用于具有公共个案、但每个个案信息不同的输入文件。</li><li><code>UPDATE</code> 用一组事务文件中的数据更新主数据文件。事务数据文件中的每个个案会修改主数据文件中与之匹配的个案，若找不到匹配的个案，则添加一个新的个案。</li></ul><p>这些命令共享其大部分语法，下文将先描述这些共性语法，然后分别用一节描述每个命令特有的语法与语义。</p><table tabindex="0"><thead><tr><th>• 合并文件的通用语法</th><th></th><th></th></tr></thead><tbody><tr><td>• ADD FILES</td><td></td><td>交错来自多个文件的个案。</td></tr><tr><td>• MATCH FILES</td><td></td><td>合并来自多个文件的个案。</td></tr><tr><td>• UPDATE</td><td></td><td>使用事务数据更新个案。</td></tr></tbody></table>',5)])])}const p=a(o,[["render",r]]);export{m as __pageData,p as default};
